try {
  const src = constants.ACCESS_RESOLVER_CODE;
  if (!src) { console.warn('ACCESS_RESOLVER_CODE constant missing'); await actions.setVariable('access', null); return; }
  const fn = new Function('globals', 'constants', 'return (' + src + ')(globals, constants);');
  const access = fn(globals, constants);
  await actions.setVariable('access', access);
} catch (e) {
  console.error('initAccess failed', e);
  await actions.setVariable('access', null);
}
